/**
 * Shared `GET /api/projects/status/events` stream (server `apps/server/src/projects`).
 *
 * The server pushes one `data: status` per project/agent status change. Screens that want fresh data
 * share a single `EventSource`: the sidebar tree (`app-sidebar.svelte`) and the `/projects` workflow
 * (`+page.svelte`) both subscribe here, so one connection serves both and it closes with the last
 * subscriber. A burst of events costs one refetch (trailing window), and a dropped stream reconnects
 * with exponential backoff. Every caller keeps its own poll as a fallback and asks `isOpen()` for the
 * delay: slower while the stream carries the changes.
 *
 * Plain module, no runes: `tests/project-status-events.test.ts` drives it with a fake `connect` and
 * fake timers.
 */

const EVENTS_URL = "/api/projects/status/events";
/** Trailing window: the refetch lands once, 80ms after the last event of a burst. */
const COALESCE_MS = 80;
const RETRY_MIN_MS = 1000;
const RETRY_MAX_MS = 30_000;

export type StatusListener = () => void;

/** What a connection reports. `close` must not call these afterwards. */
export type StreamHooks = {
	open: () => void;
	error: () => void;
	message: (data: string) => void;
};

export type Stream = { close: () => void };
/** Seam for tests; the production one is `EventSource`. */
export type Connect = (url: string, hooks: StreamHooks) => Stream;

type Timers = {
	set: (callback: () => void, ms: number) => unknown;
	clear: (handle: unknown) => void;
};

export type StatusEventsOptions = {
	url?: string;
	coalesceMs?: number;
	retryMinMs?: number;
	retryMaxMs?: number;
	connect?: Connect;
	timers?: Timers;
};

export type StatusEvents = {
	/** Refetch hook. The returned unsubscribe closes the stream once the last one leaves. */
	subscribe(listener: StatusListener): () => void;
	/** True while the shared stream is connected; pollers slow down while it is. */
	isOpen(): boolean;
	/** Live subscribers. The stream exists only while this is above zero. */
	subscribers(): number;
};

function connectEventSource(url: string, hooks: StreamHooks): Stream {
	const source = new EventSource(url);
	source.onopen = () => hooks.open();
	source.onerror = () => hooks.error();
	source.onmessage = (event: MessageEvent) => hooks.message(typeof event.data === "string" ? event.data : "");
	return {
		close() {
			source.onopen = null;
			source.onerror = null;
			source.onmessage = null;
			source.close();
		},
	};
}

const realTimers: Timers = {
	set: (callback, ms) => setTimeout(callback, ms),
	clear: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
};

export function createStatusEvents(options: StatusEventsOptions = {}): StatusEvents {
	const url = options.url ?? EVENTS_URL;
	const coalesceMs = options.coalesceMs ?? COALESCE_MS;
	const retryMinMs = options.retryMinMs ?? RETRY_MIN_MS;
	const retryMaxMs = options.retryMaxMs ?? RETRY_MAX_MS;
	const connect = options.connect ?? connectEventSource;
	const timers = options.timers ?? realTimers;

