	const name = role.harness === "claude" ? role.model : role.model.split("/").slice(1).join("/") || role.model;
	return `${role.harness} · ${name} · ${role.effort}`;
}

export function fullModel(role: RoleModel): string {
	return `${role.harness} ${role.model} (${role.effort})`;
}

