/**
 * The one state a worktree card or a sidebar project row shows, mirrored from the server's
 * `workflow::Kind` (`apps/server/src/workflow/mod.rs`), which also owns the priority between
 * Gate result, Lead review and task status. The client only draws it: `status-icon.svelte`.
 * Plan: `docs/plan/261001-unified-status-icon.md`.
 */
export type StatusKind =
	"idle" | "standby" | "queued" | "done" | "running" | "reviewing" | "asking" | "paused" | "failed";

/** Least to most urgent, the server's `Kind` order. */
const ORDER: StatusKind[] = ["idle", "standby", "queued", "done", "running", "reviewing", "asking", "paused", "failed"];

/** The more urgent of two kinds, as the server's `max` picks it. */
export function urgent(a: StatusKind, b: StatusKind): StatusKind {
	return ORDER.indexOf(a) >= ORDER.indexOf(b) ? a : b;
}

/** Accessible name and tooltip lead for each kind. */
export const STATUS_LABEL: Record<StatusKind, string> = {
	idle: "Idle",
	standby: "Terminal open",
	queued: "Queued",
	done: "Done",
	running: "Running",
	reviewing: "Lead reviewing",
	asking: "Waiting for your answer",
	paused: "Paused",
	failed: "Gate failed",
};

