/** 터미널 화면의 경로 글(`docs/a.md`, `apps/+page.svelte:12`)을 찾아 Ctrl+클릭으로 파일 보기에 여는 링크의 순수 부분.
 *  화면에 찍힌 글자만 보고 후보를 뽑고, 진짜 있는 파일인지는 서버가 가린다(Orca terminal-link-handlers). */

export type PathRef = {
	/** 글 안에서 경로 부분의 UTF-16 범위 `[start, end)`. 줄 번호 꼬리(`:12`)는 뺀다. */
	start: number;
	end: number;
	path: string;
	line?: number;
	column?: number;
};

/** 경로를 끊는 글자. 공백, 따옴표, 괄호, 쉼표·세미콜론, `=`(`--dir=docs/a.md`). `*` 와 `?` 는 끊지 않고 뒤에서
 *  글롭(`docs/*.md`)으로 가려 버린다. */
const TOKEN = /[^\s"'`<>()[\]{}|,;=]+/gu;
const TRAILING = /[.:!?]+$/u;
/** `:12`, `:12:3`, `#L12`, `#L12C3`. */
const LOCATION = /(?::(\d+)(?::(\d+))?|#L(\d+)(?:C(\d+))?)$/u;
/** 확장자는 글자가 하나는 있어야 한다: `1.5`, `3.14` 는 파일이 아니다. */
const EXTENSION = /\.[0-9]*[A-Za-z][A-Za-z0-9]{0,9}$/u;
const MAX_REFS = 40;

/** `text` 안의 경로 후보. 있는지는 모른다. */
export function findPathRefs(text: string): PathRef[] {
	const refs: PathRef[] = [];
	for (const match of text.matchAll(TOKEN)) {
		if (refs.length >= MAX_REFS) break;
		let start = match.index;
		let token = match[0];
		/* 에이전트가 쓰는 멘션 `@docs/a.md`. */
		if (token.startsWith("@")) {
			token = token.slice(1);
			start += 1;
		}
		if (token.includes("*") || token.includes("://") || token.startsWith("-")) continue;
		const stripped = token.replace(TRAILING, "");
		if (!stripped) continue;
		const location = stripped.match(LOCATION);
