 */
import { getContext, setContext } from "svelte";

const KEY = Symbol("agent-focus");

export function provideAgentFocus(focus: () => void) {
	setContext(KEY, focus);
}

/**
 * 팝오버 `onCloseAutoFocus` 에 넘긴다. Agent 밖이면 undefined(기본 동작).
 * 닫힌 뒤 초점이 몸통 · 닫히는 상자 · 닫힌 트리거에 남았을 때만 입력창으로 옮긴다: 다른 곳을 눌러 닫았으면 그대로 둔다.
 */
export function agentCloseFocus(): ((event: Event) => void) | undefined {
	const focus = getContext<(() => void) | undefined>(KEY);
	if (!focus) return undefined;
	return (event) => {
		/* 다른 팝오버 안에 겹쳐 열린 것(모델 상자의 manual 칸)은 제 트리거로: 입력창으로 가면 바깥 상자가 닫힌다. */
		if (document.querySelectorAll("[data-slot=popover-content]").length > 1) return;
		event.preventDefault();
		requestAnimationFrame(() => {
			/* 닫히는 상자는 나가는 움직임 동안 아직 DOM 에 있어 초점이 그 안에 남아 있을 수 있다. */
			const active = document.activeElement;
			if (
				!active ||
				active === document.body ||
				active.closest("[data-slot=popover-content]") ||
				active.getAttribute("aria-expanded") === "false"
			)
				focus();
		});
	};
}

