   `fade` 는 opacity 만 — 칸 폭을 호스트가 직접 옮기는 Overview Dock(그리드 열 전이). 길이 · 곡선은 `--panel-fold-*`. */
import { cubicOut } from "svelte/easing";
import type { TransitionConfig } from "svelte/transition";

export type BoxFold = "flex" | "fade";

function foldMs(node: HTMLElement) {
	const raw = getComputedStyle(node).getPropertyValue("--panel-fold-duration").trim();
	const ms = raw.endsWith("ms") ? parseFloat(raw) : parseFloat(raw) * 1000;
	return Number.isFinite(ms) ? ms : 200;
}

export function boxFold(node: HTMLElement, { mode = "flex" }: { mode?: BoxFold } = {}): TransitionConfig {
	const base = { duration: foldMs(node), easing: cubicOut };
	if (mode === "fade") return { ...base, css: (t) => `opacity: ${t}` };
	const min = parseFloat(getComputedStyle(node).minHeight) || 0;
	return {
		...base,
		css: (t) => `flex-grow: ${t}; min-height: ${min * t}px; opacity: ${t}`,
	};
}

