/**
 * The task a harness wrote into its terminal title, or null when the title is only the app
 * (no topic yet).
 *
 * - `claude`: a spinner glyph, then the topic (`✳ Terminal blind overlay`). `Claude Code` is idle.
 * - `pi`: `π - fix login - dashboard` — the session name between the app title and the folder.
 *   The session itself may contain ` - ` (`Pi-Bolt - a - b - dashboard`).
 */

/** Claude Code's own title, with or without the spinner. Not a task. */
const CLAUDE_IDLE = "Claude Code";

export function taskTitle(harness: "pi" | "claude", title: string): string | null {
	if (harness === "claude") return claudeTopic(title);
	return piSession(title);
}

/** Drop one leading spinner glyph (✳, a braille frame, …) and the space after it. */
function claudeTopic(title: string): string | null {
	const trimmed = title.trim();
	if (!trimmed) return null;
	const [first] = [...trimmed];
	const topic = /^\p{L}/u.test(first) ? trimmed : trimmed.slice(first.length).trim();
	if (!topic || topic === CLAUDE_IDLE) return null;
	return topic;
}

/** Middle of `app - session - folder`. The session may itself contain ` - `. */
function piSession(title: string): string | null {
	const parts = title.split(" - ");
	if (parts.length < 3) return null;
	const session = parts.slice(1, -1).join(" - ").trim();
	return session || null;
}
